// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {
	// LogoutCurrentSession Revoke the authenticated browser session
	// (POST /api/auth/logout)
	LogoutCurrentSession(ctx context.Context, request LogoutCurrentSessionRequestObject) (LogoutCurrentSessionResponseObject, error)
	// BeginSnapTradeAuthorization Begin a short-lived hosted SnapTrade authorization attempt
	// (POST /api/auth/snaptrade/authorize)
	BeginSnapTradeAuthorization(ctx context.Context, request BeginSnapTradeAuthorizationRequestObject) (BeginSnapTradeAuthorizationResponseObject, error)
	// CompleteSnapTradeAuthorization Consume a single-use hosted authorization callback
	// (GET /api/auth/snaptrade/callback)
	CompleteSnapTradeAuthorization(ctx context.Context, request CompleteSnapTradeAuthorizationRequestObject) (CompleteSnapTradeAuthorizationResponseObject, error)
	// GetAuthorizationStatus Report categorical authorization availability and session state
	// (GET /api/auth/status)
	GetAuthorizationStatus(ctx context.Context, request GetAuthorizationStatusRequestObject) (GetAuthorizationStatusResponseObject, error)
	// GetPortfolioInclusion Return the authenticated owner's committed and pending account inclusion
	// (GET /api/portfolio/inclusion)
	GetPortfolioInclusion(ctx context.Context, request GetPortfolioInclusionRequestObject) (GetPortfolioInclusionResponseObject, error)
	// ConfirmPortfolioInclusion Confirm the authenticated owner's complete target account set
	// (POST /api/portfolio/inclusion)
	ConfirmPortfolioInclusion(ctx context.Context, request ConfirmPortfolioInclusionRequestObject) (ConfirmPortfolioInclusionResponseObject, error)
	// GetPortfolioInventory Return or bootstrap the authenticated owner's masked inventory
	// (GET /api/portfolio/inventory)
	GetPortfolioInventory(ctx context.Context, request GetPortfolioInventoryRequestObject) (GetPortfolioInventoryResponseObject, error)
	// RetryPortfolioInventory Explicitly retry the authenticated owner's inventory bootstrap
	// (POST /api/portfolio/inventory/retry)
	RetryPortfolioInventory(ctx context.Context, request RetryPortfolioInventoryRequestObject) (RetryPortfolioInventoryResponseObject, error)
	// GetPortfolioShowcase Return the authenticated owner's persisted portfolio showcase
	// (GET /api/portfolio/showcase)
	GetPortfolioShowcase(ctx context.Context, request GetPortfolioShowcaseRequestObject) (GetPortfolioShowcaseResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

